using System;
using System.Collections;
using FMODUnity;
using LittleLeo;
using LittleLeo.Events;
using UnityEngine;

namespace Astrea;

public class CorruptedAnimalSpriteControl : SpriteControl
{
	[Header("Purified Animation")]
	[SerializeField]
	private float purifyShakeDuration;

	[SerializeField]
	private float purifyShakeAmount;

	[Header("Defeated Animation")]
	[SerializeField]
	private float shakeAmount;

	[Header("Flee Animation")]
	[SerializeField]
	private float delayToStartPurifiedSpineAnimation;

	[SerializeField]
	private float defeatedSpineAnimationDefaultMixDuration;

	[Header("Stay Sentinel Animation")]
	[SerializeField]
	private float staySentinelShakeDuration;

	[SerializeField]
	private float staySentinelShakeAmount;

	[SerializeField]
	private AnimationCurve staySentinelShakeCurve;

	[SerializeField]
	private CompanionSFXData companionSFXData;

	[Header("Flee Away Animation")]
	[SerializeField]
	private float jumpDuration;

	[SerializeField]
	private AnimationCurve jumpCurve;

	[SerializeField]
	private float jumpMovementAmount;

	[SerializeField]
	private float spawnOutsideScreenAdjustment;

	[SerializeField]
	private float spawningAndLeavingMovementDuration;

	[SerializeField]
	private AnimationCurve movementCurve;

	[Header("Vanish Animation")]
	[SerializeField]
	private float vanishDuration;

	[SerializeField]
	private AnimationCurve vanishCurve;

	[Header("Corrupted Animal Components")]
	private CorruptedAnimalCorruptionStats corruptedAnimalCorruptionStats;

	[SerializeField]
	private CorruptedAnimalCorruptionGauge corruptedAnimalCorruptionGauge;

	[SerializeField]
	private CorruptedAnimalEffects corruptedAnimalEffects;

	[SerializeField]
	private UnitsDiceActivation unitsDiceActivation;

	[SerializeField]
	private UnitDialogue unitDialogue;

	[Header("Current Corrupted Animals")]
	[SerializeField]
	private CurrentCorruptedAnimals currentCorruptedAnimals;

	[Header("Boss Defeated")]
	[SerializeField]
	private VoidEvent OnBossDefeated;

	[Header("SFX")]
	[SerializeField]
	private EventReference enemyGenericAttackSFX;

	[SerializeField]
	private EventReference enemyGenericPurifiedSFX;

	[SerializeField]
	private EventReference enemyGenericPurifiedRunAwaySFX;

	[SerializeField]
	private EventReference enemyGenericPurifiedVanishSFX;

	[Header("VFX")]
	[SerializeField]
	private GameObject defeatedVFXPrefab;

	[SerializeField]
	private GameObject corruptedSentinelDefeatedVFXPrefab;

	[Header("Achievement")]
	[SerializeField]
	private StellarHasteAchievementData stellarHasteAchievementData;

	[Header("Screenshake")]
	[SerializeField]
	private FloatFloatEvent OnScreenShake;

	private CorruptedAnimalData corruptedAnimalData;

	private SpriteRenderer brokenCorruptedCompanionSmokeSprite;

	private ParticleEmissionController particleEmissionControllerCorruptedSentinelBrokenVFX;

	private OrionAstrarium orionAstrarium;

	private bool disablePurifiedAnimationForTutorial;

	public CorruptedAnimalData CorruptedAnimalData => corruptedAnimalData;

	public OrionAstrarium OrionAstrarium => orionAstrarium;

	public void SetDisablePurifiedAnimationForTutorial(bool value)
	{
		disablePurifiedAnimationForTutorial = value;
	}

	public void Initialize(CorruptedAnimalData corruptedAnimalData, CorruptedAnimalCorruptionStats corruptedAnimalCorruptionStats, bool startBattleInitialize)
	{
		this.corruptedAnimalData = corruptedAnimalData;
		this.corruptedAnimalCorruptionStats = corruptedAnimalCorruptionStats;
		animationData = corruptedAnimalData.AnimationData;
		if (corruptedAnimalData.EnableUnitsMiscData)
		{
			enableUnitsMiscData = true;
			unitsMiscData = corruptedAnimalData.UnitsMiscData;
		}
		else
		{
			enableUnitsMiscData = false;
			unitsMiscData = null;
		}
		SpawnSkeletonAnimation();
		InitializeBrokenCorruptedSentinelVFXs(startBattleInitialize);
		ResetOutlineBrightness();
		CheckEnvironmentPrefab();
	}

	protected override void SpawnSkeletonAnimation()
	{
		base.SpawnSkeletonAnimation();
		InitializeSkeletonTransform();
		InitializeMaterials();
		RandomizeAnimationStartingFrame();
	}

	private void InitializeBrokenCorruptedSentinelVFXs(bool startBattleInitialize)
	{
		brokenCorruptedCompanionSmokeSprite = skeletonTransform.GetChild(3).GetComponent<SpriteRenderer>();
		particleEmissionControllerCorruptedSentinelBrokenVFX = skeletonTransform.GetChild(4).GetComponent<ParticleEmissionController>();
		if (startBattleInitialize)
		{
			brokenCorruptedCompanionSmokeSprite.gameObject.SetActive(value: false);
			particleEmissionControllerCorruptedSentinelBrokenVFX.gameObject.SetActive(value: false);
		}
		FadeBrokenCompanionSmokeSprite(value: false, 0.4f);
		particleEmissionControllerCorruptedSentinelBrokenVFX.SetActiveEmissionModule(value: false);
	}

	private void InitializeSkeletonTransform()
	{
		skeletonTransform.position = base.transform.position;
		skeletonTransform.gameObject.SetActive(value: true);
	}

	private void InitializeMaterials()
	{
		lightSprite.material.SetFloat("_TextTween", 0f);
		skeletonMeshRenderer.SetRendererFloat(materialPropertyBlock, "_DissolveValue", 0f);
	}

	private void RandomizeAnimationStartingFrame()
	{
		float maxInclusive = GetCurrentTrackEntry().Animation.Duration * 0.9f;
		GetCurrentTrackEntry().TrackTime = UnityEngine.Random.Range(0f, maxInclusive);
	}

	public void FadeBrokenCompanionSmokeSprite(bool value, float duration)
	{
		if (value)
		{
			brokenCorruptedCompanionSmokeSprite.gameObject.SetActive(value: true);
		}
		ReferenceSingleton<CoroutineHandler>.Instance.Run(brokenCorruptedCompanionSmokeSprite.FadeSprite(value ? 1 : 0, duration, staySentinelShakeCurve, delegate
		{
			if (!value)
			{
				brokenCorruptedCompanionSmokeSprite.gameObject.SetActive(value: false);
			}
		}));
	}

	private void CheckEnvironmentPrefab()
	{
		orionAstrarium = null;
		if (enableUnitsMiscData && unitsMiscData.EnableEnvironmentPrefab)
		{
			orionAstrarium = UnityEngine.Object.Instantiate(unitsMiscData.EnvironmentPrefab).GetComponentInChildren<OrionAstrarium>();
		}
	}

	public void SetCorruptedAnimalData(CorruptedAnimalData corruptedAnimalData)
	{
		this.corruptedAnimalData = corruptedAnimalData;
		animationData = corruptedAnimalData.AnimationData;
	}

	protected override void InitializeMaterialProperties()
	{
		base.InitializeMaterialProperties();
		skeletonMeshRenderer.SetRendererFloat(materialPropertyBlock, "_EffectTexAlpha", 1f);
	}

	private void DisableSkeleton()
	{
		skeletonTransform.gameObject.SetActive(value: false);
	}

	public IEnumerator PlayAttackAnimation(AnimationType animationType = AnimationType.Attack, Action activateDiceAction = null, bool overCorruption = false)
	{
		bool customAttackAnimationLogic = false;
		if ((!overCorruption || animationData.UseCustomAttackAnimationLogicOnOverCorruptionAttack) && animationData.EnableCustomAttackAnimationLogic)
		{
			AnimationType customAttackAnimationType = animationData.GetCustomAttackAnimationType(this, corruptedAnimalData.EnemySFXData);
			if (customAttackAnimationType != AnimationType.Null)
			{
				customAttackAnimationLogic = true;
				PlayEnemyActivationVFX();
				PlayEnemyActivationScreenshake();
				yield return StartCoroutine(PlayAnimationForcedCoroutine(customAttackAnimationType, AnimationChangeType.ReturnToPrevious, activateDiceAction));
			}
		}
		if (customAttackAnimationLogic)
		{
			yield break;
		}
		if (animationType != AnimationType.Attack)
		{
			if (!HasAnimation(animationType))
			{
				yield break;
			}
			EnemySFXData enemySFXData = corruptedAnimalData.EnemySFXData;
			if ((bool)enemySFXData && enemySFXData.EnableEnemyOverCorruptAttackSkillSFX)
			{
				if (enemySFXData.EnableEnemyOverCorruptAttackSkillDelay)
				{
					InvokeAlternatives.Invoke(ReferenceSingleton<CoroutineHandler>.Instance, enemySFXData.EnemyOverCorruptAttackSkillDelay, delegate
					{
						ReferenceSingleton<SFXHandler>.Instance.PlaySFX(enemySFXData.EnemyOverCorruptAttackSkillSFX);
					});
				}
				else
				{
					ReferenceSingleton<SFXHandler>.Instance.PlaySFX(enemySFXData.EnemyOverCorruptAttackSkillSFX);
				}
			}
			AnimationChangeType animationChangeType = AnimationChangeType.ReturnToPrevious;
			if (animationData.DontReturnToPreviousAnimationAfterOverCorruptAnimation)
			{
				animationChangeType = AnimationChangeType.StayInTheNewAnimationNotLooping;
			}
			yield return StartCoroutine(PlayAnimationForcedCoroutine(animationType, animationChangeType, activateDiceAction));
		}
		else if (HasAnimation(AnimationType.Attack))
		{
			PlayEnemyAttackSFX();
			PlayEnemyActivationVFX();
			PlayEnemyActivationScreenshake();
			AnimationChangeType animationChangeType2 = AnimationChangeType.ReturnToPrevious;
			if (corruptedAnimalData.AnimationData.EnableCustomAttackAnimationChangeType)
			{
				animationChangeType2 = corruptedAnimalData.AnimationData.CustomAttackAnimationChangeType;
			}
			else if (corruptedAnimalData.AnimationData.CollapsedAstrea)
			{
				animationChangeType2 = AnimationChangeType.StayInTheNewAnimationLooping;
			}
			yield return StartCoroutine(PlayAnimationForcedCoroutine(AnimationType.Attack, animationChangeType2, activateDiceAction));
		}
		else
		{
			PlayEnemyAttackSFX();
			PlayEnemyActivationVFX();
			PlayEnemyActivationScreenshake();
			yield return StartCoroutine(unitsDiceActivation.ActivationAnimation(activateDiceAction));
		}
	}

	private void PlayEnemyAttackSFX()
	{
		EnemySFXData enemySFXData = corruptedAnimalData.EnemySFXData;
		if ((bool)enemySFXData)
		{
			if (enemySFXData.EnableEnemyAttackDelay)
			{
				InvokeAlternatives.Invoke(ReferenceSingleton<CoroutineHandler>.Instance, enemySFXData.EnemyAttackDelay, delegate
				{
					DecideWhichSoundToPlayAndPlay();
				});
			}
			else
			{
				DecideWhichSoundToPlayAndPlay();
			}
		}
		else
		{
			PlayEnemyGenericAttackSFX();
		}
	}

	private void DecideWhichSoundToPlayAndPlay()
	{
		EnemySFXData enemySFXData = corruptedAnimalData.EnemySFXData;
		if (enemySFXData.EnableEnemyAttack)
		{
			enemySFXData.PlayEnemyAttackSFX();
		}
		else
		{
			PlayEnemyGenericAttackSFX();
		}
	}

	private void PlayEnemyGenericAttackSFX()
	{
		ReferenceSingleton<SFXHandler>.Instance.PlaySFX(enemyGenericAttackSFX);
	}

	private void PlayEnemyActivationVFX()
	{
		if ((bool)unitsMiscData && (!(animationData != null) || !animationData.CollapsedAstrea))
		{
			unitsMiscData.SpawnActivationVFX(base.transform.position);
		}
	}

	private void PlayEnemyActivationScreenshake()
	{
		if ((bool)unitsMiscData)
		{
			unitsMiscData.CheckActivationScreenshake(OnScreenShake);
		}
	}

	public override void OnReceiveCorruption()
	{
		base.OnReceiveCorruption();
		animationData.OnReceiveCorruption(this, corruptedAnimalCorruptionStats);
	}

	public override void OnReceivePurify()
	{
		base.OnReceivePurify();
		CoroutineUtility.ShakeRoutine(this, animationSkeleton.transform, purifyShakeDuration, purifyShakeAmount);
		if (!animationData.OnReceivePurify(this, corruptedAnimalCorruptionStats))
		{
			PlayAnimation(AnimationType.ReceiveDamage);
		}
	}

	public void OnReceiveFatalDamage(bool minionDefeatedByBossDefeat)
	{
		PlayVisualEffect(VisualEffectType.Purify);
		if (disablePurifiedAnimationForTutorial)
		{
			if (enableUnitsMiscData && unitsMiscData.EnableOnReceiveFatalDamageVoidEvent)
			{
				unitsMiscData.OnReceiveFatalDamage.Raise();
			}
			return;
		}
		GameStateManager instance = ReferenceSingleton<GameStateManager>.Instance;
		instance.ActionsQueueState.EnqueueCompanionAndEnemyDefeatSetupCoroutines(OnReceiveFatalDamageSetupEnemy());
		instance.SetActionsQueueState();
		switch (animationData.AnimalPurifiedAnimation)
		{
		case AnimalPurifiedAnimation.FleeAway:
			EnqueueOrPlayAnimation(DefeatedAnimationWithPurifiedSprite(stayInPlace: false, minionDefeatedByBossDefeat), minionDefeatedByBossDefeat);
			break;
		case AnimalPurifiedAnimation.StayInPlace:
			EnqueueOrPlayAnimation(DefeatedAnimationWithPurifiedSprite(stayInPlace: true, minionDefeatedByBossDefeat), minionDefeatedByBossDefeat);
			break;
		case AnimalPurifiedAnimation.Vanish:
			EnqueueOrPlayAnimation(VanishAnimation(minionDefeatedByBossDefeat), minionDefeatedByBossDefeat);
			break;
		}
		if (!minionDefeatedByBossDefeat)
		{
			corruptedAnimalEffects.OnPurgedEffects();
		}
	}

	private void EnqueueOrPlayAnimation(IEnumerator defeatedCoroutine, bool minionDefeatedByBossDefeat)
	{
		if (!minionDefeatedByBossDefeat)
		{
			GameStateManager instance = ReferenceSingleton<GameStateManager>.Instance;
			instance.ActionsQueueState.EnqueueCompanionAndEnemyDefeatAnimationCoroutines(defeatedCoroutine);
			instance.SetActionsQueueState();
		}
		else
		{
			ReferenceSingleton<CoroutineHandler>.Instance.Run(defeatedCoroutine);
		}
	}

	private IEnumerator OnReceiveFatalDamageSetupEnemy()
	{
		if (!corruptedAnimalData.AnimationData.AstreaFirstPhase)
		{
			yield return new WaitForSeconds(0.2f);
			unitsDiceActivation.StoreDice();
			corruptedAnimalCorruptionGauge.gameObject.SetActive(value: false);
		}
	}

	private IEnumerator VanishAnimation(bool minionDefeatedByBossDefeat)
	{
		if (unitDialogue.HasDialogueTypeShowDialogueBoxRandomDialogue(DialogueTypeEnum.DEFEAT))
		{
			yield return new WaitForSeconds(0.5f);
		}
		corruptedAnimalEffects.RemoveAllEffectsWithCallbacks();
		UnitsMiscDataChecks();
		PlayEnemyDefeatedVFX();
		if (!minionDefeatedByBossDefeat)
		{
			PlayEnemyVanishSFX();
		}
		Debug.Log("Vanish Animation: Start");
		CoroutineUtility.ShakeRoutine(this, animationSkeleton.transform, vanishDuration, shakeAmount);
		ReferenceSingleton<CoroutineHandler>.Instance.Run(CoroutineUtility.CurveRoutine(vanishDuration, vanishCurve, null, delegate(float t, float v)
		{
			skeletonMeshRenderer.SetRendererFloat(materialPropertyBlock, "_DissolveValue", Mathf.Lerp(0f, 1f, v));
			shadowSprite.SetAlpha(Mathf.Lerp(1f, 0f, v));
			lightSprite.SetAlpha(Mathf.Lerp(1f, 0f, v));
		}, delegate
		{
			Debug.Log("Vanish Animation: End");
			if (enableUnitsMiscData)
			{
				if (!unitsMiscData.DisableSkeletonDisablingAfterVanishing)
				{
					DisableSkeleton();
				}
			}
			else
			{
				DisableSkeleton();
			}
			if (animationData.EnableAfterVanishAnimationLogic)
			{
				animationData.AfterVanishAnimationLogic(this);
			}
		}));
		yield return new WaitForSeconds(vanishDuration - 0.5f);
		ReferenceSingleton<PoolHandler>.Instance.StoreObject(base.gameObject);
		yield return InvokeAlternatives.WaitForFrames(3);
	}

	private void PlayEnemyDefeatedVFX()
	{
		if ((bool)unitsMiscData)
		{
			unitsMiscData.SpawnDefeatedVFX(base.transform.position, defeatedVFXPrefab, corruptedSentinelDefeatedVFXPrefab);
		}
	}

	private void UnitsMiscDataChecks()
	{
		if (enableUnitsMiscData)
		{
			if (unitsMiscData.EnableOnBossDefeatedEvent)
			{
				OnBossDefeated.Raise();
			}
			if (unitsMiscData.EnableOnReceiveFatalDamageVoidEvent)
			{
				unitsMiscData.OnReceiveFatalDamage.Raise();
			}
			if (unitsMiscData.OnReceiveFatalDamageDefeatMinions)
			{
				currentCorruptedAnimals.InstantlyDefeatAllMinions();
			}
			if (unitsMiscData.EnableDefeatEnemyAchievementData)
			{
				unitsMiscData.DefeatEnemyAchievementData.Unlock();
			}
			if (unitsMiscData.EnableIfIHadFailedAchievementData)
			{
				unitsMiscData.IfIHadFailedAchievementData.Unlock();
			}
			if (unitsMiscData.EnableStellarHasteAchievementDataCheck)
			{
				stellarHasteAchievementData.Unlock();
			}
		}
	}

	private void PlayEnemyVanishSFX()
	{
		EnemySFXData enemySFXData = corruptedAnimalData.EnemySFXData;
		if ((bool)enemySFXData)
		{
			if (enemySFXData.EnableVanish)
			{
				ReferenceSingleton<SFXHandler>.Instance.PlaySFX(enemySFXData.Vanish);
			}
			else
			{
				PlayGenericPurifiedVanishSFX();
			}
		}
		else
		{
			PlayGenericPurifiedVanishSFX();
		}
	}

	private void PlayGenericPurifiedVanishSFX()
	{
		ReferenceSingleton<SFXHandler>.Instance.PlaySFX(enemyGenericPurifiedVanishSFX);
	}

	private IEnumerator DefeatedAnimationWithPurifiedSprite(bool stayInPlace, bool minionDefeatedByBossDefeat)
	{
		UnitsMiscDataChecks();
		corruptedAnimalEffects.RemoveAllEffectsWithCallbacks();
		bool flag = false;
		if (stayInPlace && (bool)unitsMiscData)
		{
			flag = unitsMiscData.IsDefeatedVFXSentinel;
		}
		if (flag)
		{
			yield return StartCoroutine(StayInPlaceSentinelAnimationCoroutine(minionDefeatedByBossDefeat));
		}
		else if ((bool)animationData)
		{
			if (animationData.EnableCustomBeingPurifiedAnimationCoroutine)
			{
				yield return StartCoroutine(animationData.CustomBeingPurifiedAnimationCoroutine(this));
			}
			else
			{
				yield return StartCoroutine(BeingPurifiedAnimationCoroutine(minionDefeatedByBossDefeat));
			}
		}
		else
		{
			yield return StartCoroutine(BeingPurifiedAnimationCoroutine(minionDefeatedByBossDefeat));
		}
		if (!corruptedAnimalData.AnimationData.AstreaFirstPhase)
		{
			ReferenceSingleton<PoolHandler>.Instance.StoreObject(base.gameObject);
		}
		yield return InvokeAlternatives.WaitForFrames(3);
		if (!stayInPlace)
		{
			_ = ReferenceSingleton<GameStateManager>.Instance.ActionsQueueState;
			ReferenceSingleton<CoroutineHandler>.Instance.StartCoroutine(AfterPurifiedAnimation());
		}
	}

	private IEnumerator StayInPlaceSentinelAnimationCoroutine(bool minionDefeatedByBossDefeat)
	{
		CoroutineUtility.ShakeRoutine(this, animationSkeleton.transform, staySentinelShakeDuration, staySentinelShakeAmount, staySentinelShakeCurve);
		StartCoroutine(lightSprite.material.TweenFloatProperty("_TextTween", 1f, staySentinelShakeDuration, staySentinelShakeCurve));
		TweenStripeEffect(staySentinelShakeDuration, staySentinelShakeCurve, 0f);
		if (!minionDefeatedByBossDefeat)
		{
			PlayEnemyPurifiedSFX();
		}
		PlayEnemyDefeatedVFX();
		ReferenceSingleton<SFXHandler>.Instance.PlaySFX(companionSFXData.Breaking);
		InvokeAlternatives.Invoke(ReferenceSingleton<CoroutineHandler>.Instance, staySentinelShakeDuration - 0.6f, delegate
		{
			FadeBrokenCompanionSmokeSprite(value: true, 0.9f);
			if (ReferenceSingleton<VFXHandler>.Instance.IsVFXEnabled())
			{
				particleEmissionControllerCorruptedSentinelBrokenVFX.gameObject.SetActive(value: true);
				particleEmissionControllerCorruptedSentinelBrokenVFX.SetActiveEmissionModule(value: true);
			}
		});
		yield return new WaitForSeconds(staySentinelShakeDuration);
		PlayAnimationForced(AnimationType.Die, AnimationChangeType.StayInTheNewAnimationNotLooping);
		SetMixDuration(0f);
		yield return new WaitForSeconds(0.1f);
	}

	public void TweenStripeEffect(float duration, AnimationCurve animationCurve, float targetAlpha)
	{
		float startingAlpha = materialPropertyBlock.GetFloat("_EffectTexAlpha");
		StartCoroutine(CoroutineUtility.CurveRoutine(duration, animationCurve, delegate(float t, float v)
		{
			skeletonMeshRenderer.SetRendererFloat(materialPropertyBlock, "_EffectTexAlpha", Mathf.Lerp(startingAlpha, targetAlpha, v));
		}));
	}

	public void TweenLight(float defeatedSpineAnimationDefaultMixDurationPicked)
	{
		StartCoroutine(lightSprite.material.TweenFloatProperty("_TextTween", 1f, defeatedSpineAnimationDefaultMixDurationPicked));
	}

	private IEnumerator BeingPurifiedAnimationCoroutine(bool minionDefeatedByBossDefeat)
	{
		if ((bool)unitsMiscData && unitsMiscData.EnableDelayBeforeBeingPurifiedAnimation)
		{
			if (ReferenceSingleton<VFXHandler>.Instance.IsVFXEnabled())
			{
				yield return new WaitForSeconds(unitsMiscData.DelayBeforeBeingPurifiedAnimation);
			}
			else
			{
				yield return new WaitForSeconds(0.5f);
			}
		}
		if (!minionDefeatedByBossDefeat)
		{
			PlayEnemyPurifiedSFX();
		}
		float defeatedSpineAnimationDefaultMixDurationPicked = defeatedSpineAnimationDefaultMixDuration;
		if ((bool)unitsMiscData && unitsMiscData.EnableCustomDefeatedSpineAnimationDefaultMixDuration)
		{
			defeatedSpineAnimationDefaultMixDurationPicked = unitsMiscData.CustomDefeatedSpineAnimationDefaultMixDuration;
		}
		float shakeDuration = delayToStartPurifiedSpineAnimation + defeatedSpineAnimationDefaultMixDurationPicked;
		float customDefeatShakeAmount = shakeAmount;
		if ((bool)unitsMiscData && unitsMiscData.EnableCustomDefeatShakeAmount && ReferenceSingleton<VFXHandler>.Instance.IsVFXEnabled())
		{
			customDefeatShakeAmount = unitsMiscData.CustomDefeatShakeAmount;
		}
		CoroutineUtility.ShakeRoutine(this, base.AnimationSkeletonTransform, shakeDuration, customDefeatShakeAmount);
		yield return new WaitForSeconds(delayToStartPurifiedSpineAnimation);
		PlayEnemyDefeatedVFX();
		if (corruptedAnimalData.AnimationData.AstreaSecondPhase)
		{
			TweenLight(defeatedSpineAnimationDefaultMixDurationPicked);
			TweenStripeEffect(defeatedSpineAnimationDefaultMixDurationPicked, CoroutineUtility.LinearCurve(), 0f);
			PlayAnimationForced(AnimationType.Die, AnimationChangeType.StayInTheNewAnimationLooping);
		}
		else if (!corruptedAnimalData.AnimationData.AstreaFirstPhase)
		{
			TweenLight(defeatedSpineAnimationDefaultMixDurationPicked);
			TweenStripeEffect(defeatedSpineAnimationDefaultMixDurationPicked, CoroutineUtility.LinearCurve(), 0f);
			PlayAnimationForced(AnimationType.Die, AnimationChangeType.StayInTheNewAnimationNotLooping);
		}
		else
		{
			PlayAnimationForced(AnimationType.Die, AnimationChangeType.StayInTheNewAnimationLooping);
		}
		SetMixDuration(defeatedSpineAnimationDefaultMixDurationPicked);
		yield return new WaitForSeconds(defeatedSpineAnimationDefaultMixDurationPicked);
		if (unitDialogue.HasDialogueTypeShowDialogueBoxRandomDialogue(DialogueTypeEnum.DEFEAT))
		{
			yield return new WaitForSeconds(2.5f);
		}
	}

	public void PlayEnemyPurifiedSFX()
	{
		EnemySFXData enemySFXData = corruptedAnimalData.EnemySFXData;
		if ((bool)enemySFXData)
		{
			if (enemySFXData.EnablePurified)
			{
				ReferenceSingleton<SFXHandler>.Instance.PlaySFX(enemySFXData.Purified);
			}
			else if (!enemySFXData.DisableGenericPurifiedSFX)
			{
				PlayGenericPurifiedSFX();
			}
		}
		else
		{
			PlayGenericPurifiedSFX();
		}
	}

	private void PlayGenericPurifiedSFX()
	{
		ReferenceSingleton<SFXHandler>.Instance.PlaySFX(enemyGenericPurifiedSFX);
	}

	private IEnumerator AfterPurifiedAnimation()
	{
		yield return ReferenceSingleton<CoroutineHandler>.Instance.Run(JumpAndTurnAnimation());
		LeaveAnimation();
	}

	private IEnumerator JumpAndTurnAnimation()
	{
		ReferenceSingleton<SFXHandler>.Instance.PlaySFX(enemyGenericPurifiedRunAwaySFX);
		Vector3 startingPosition = animationSkeleton.transform.position;
		Vector3 finalPosition = animationSkeleton.transform.position + Vector3.up * jumpMovementAmount;
		yield return ReferenceSingleton<CoroutineHandler>.Instance.Run(CoroutineUtility.CurveRoutine(jumpDuration, jumpCurve, delegate(float t, float v)
		{
			animationSkeleton.transform.position = Vector3.Lerp(startingPosition, finalPosition, v);
		}));
		yield return new WaitForSeconds(0.2f);
		Vector3 localScale = skeletonTransform.transform.localScale;
		skeletonTransform.transform.localScale = new Vector3(localScale.x * -1f, localScale.y, localScale.z);
		yield return new WaitForSeconds(0.15f);
	}

	private void PlayEnemyPurifiedRunAwaySFX()
	{
		EnemySFXData enemySFXData = corruptedAnimalData.EnemySFXData;
		if ((bool)enemySFXData)
		{
			if (enemySFXData.EnablePurifiedRunAway)
			{
				ReferenceSingleton<SFXHandler>.Instance.PlaySFX(enemySFXData.PurifiedRunAway);
			}
			else
			{
				PlayGenericPurifiedRunAwaySFX();
			}
		}
		else
		{
			PlayGenericPurifiedRunAwaySFX();
		}
	}

	private void PlayGenericPurifiedRunAwaySFX()
	{
		ReferenceSingleton<SFXHandler>.Instance.PlaySFX(enemyGenericPurifiedRunAwaySFX);
	}

	private void LeaveAnimation()
	{
		Vector3 startPosition = skeletonTransform.transform.position;
		Vector3 finalPosition = skeletonTransform.transform.position + Vector3.right * spawnOutsideScreenAdjustment;
		ReferenceSingleton<CoroutineHandler>.Instance.Run(CoroutineUtility.CurveRoutine(spawningAndLeavingMovementDuration, movementCurve, delegate(float t, float v)
		{
			skeletonTransform.transform.position = Vector3.Lerp(startPosition, finalPosition, v);
		}, delegate
		{
			DisableSkeleton();
		}));
	}

	public void SetLightToBlue()
	{
		lightSprite.material.SetFloat("_TextTween", 1f);
	}

	public void DisableLight()
	{
		lightSprite.gameObject.SetActive(value: false);
	}

	public void FadeInLight()
	{
		lightSprite.material.SetAlpha(0f);
		lightSprite.gameObject.SetActive(value: true);
		StartCoroutine(lightSprite.material.TweenFloatProperty("_Alpha", 1f, 0.5f));
	}
}
